price_badge.expr:
(
  $priceByModel := {
    "seedance-1-5-pro": {
      "480p":[0.12,0.12],
      "720p":[0.26,0.26],
      "1080p":[0.58,0.59]
    },
    "seedance-1-0-pro": {
      "480p":[0.23,0.24],
      "720p":[0.51,0.56],
      "1080p":[1.18,1.22]
    },
    "seedance-1-0-pro-fast": {
      "480p":[0.09,0.1],
      "720p":[0.21,0.23],
      "1080p":[0.47,0.49]
    }
  };
  $model := widgets.model;
  $modelKey :=
    $contains($model, "seedance-1-5-pro")      ? "seedance-1-5-pro" :
    $contains($model, "seedance-1-0-pro-fast") ? "seedance-1-0-pro-fast" :
    "seedance-1-0-pro";
  $resolution := widgets.resolution;
  $resKey :=
    $contains($resolution, "1080") ? "1080p" :
    $contains($resolution, "720")  ? "720p" :
    "480p";
  $modelPrices := $lookup($priceByModel, $modelKey);
  $baseRange := $lookup($modelPrices, $resKey);
  $min10s := $baseRange[0];
  $max10s := $baseRange[1];
  $scale := widgets.duration / 10;
  $audioMultiplier := ($modelKey = "seedance-1-5-pro" and widgets.generate_audio) ? 2 : 1;
  $minCost := $min10s * $scale * $audioMultiplier;
  $maxCost := $max10s * $scale * $audioMultiplier;
  ($minCost = $maxCost)
    ? {"type":"usd","usd": $minCost, "format": { "approximate": true }}
    : {"type":"range_usd","min_usd": $minCost, "max_usd": $maxCost, "format": { "approximate": true }}
)

(
  $model := $string(widgets.model);
  $sp := $string($lookup(widgets, "model.size_preset"));
  $w := $lookup(widgets, "model.width");
  $h := $lookup(widgets, "model.height");
  $px := ($type($w) = "number" and $type($h) = "number") ? $w * $h : 0;
  $refs := $lookup(inputGroups, "model.images");
  $extra := ($type($refs) = "number" and $refs > 1) ? ($refs - 1) * 0.003 : 0;
  $isPro := $contains($model, "5.0 pro");
  $isCustom := $contains($sp, "custom");
  $sizeKnown := $isCustom ? $px > 0 : ($contains($sp, "1k") or $contains($sp, "2k"));
  $proPrice := $isCustom
                 ? ($px < 2610000 ? 0.045 : 0.09)
                 : ($contains($sp, "1k") ? 0.045 : 0.09);
  ($isPro and ($sizeKnown = false))
    ? {
        "type": "range_usd",
        "min_usd": 0.045 + $extra,
        "max_usd": 0.09 + $extra,
        "format": { "suffix": "/Image", "approximate": true }
      }
    : {
        "type": "usd",
        "usd": $isPro ? $proPrice + $extra
               : $contains($model, "5.0 lite") ? 0.035
               : $contains($model, "4-5") ? 0.04
               : 0.03,
        "format": { "suffix": $isPro ? "/Image" : " x images/Run", "approximate": true }
      }
)

(
  $m := widgets.model;
  $contains($m, "gemini-2.5-flash") ? {
    "type": "list_usd",
    "usd": [0.0003, 0.0025],
    "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens"}
  }
  : $contains($m, "gemini-2.5-pro") ? {
    "type": "list_usd",
    "usd": [0.00125, 0.01],
    "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
  }
  : ($contains($m, "gemini-3-pro-preview") or $contains($m, "gemini-3-1-pro")) ? {
    "type": "list_usd",
    "usd": [0.002, 0.012],
    "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
  }
  : $contains($m, "gemini-3-1-flash-lite") ? {
    "type": "list_usd",
    "usd": [0.00025, 0.0015],
    "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
  }
  : {"type":"text", "text":"Token-based"}
)

(
  $m := widgets.model;
  $contains($m, "lite") ? {
    "type": "list_usd",
    "usd": [0.00025, 0.0015],
    "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
  }
  : ($contains($m, "3.7 flash") or $contains($m, "3.8 flash")) ? {
    "type": "list_usd",
    "usd": [0.002145, 0.010725],
    "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
  }
  : $contains($m, "3.5 flash") ? {
    "type": "list_usd",
    "usd": [0.0015, 0.009],
    "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
  }
  : {
    "type": "list_usd",
    "usd": [0.002, 0.012],
    "format": { "approximate": true, "separator": "-", "suffix": " per 1K tokens" }
  }
)

(
  $ranges := {
    "gpt-image-1": {
      "low":    [0.011, 0.02],
      "medium": [0.042, 0.07],
      "high":   [0.167, 0.25]
    },
    "gpt-image-1.5": {
      "low":    [0.009, 0.02],
      "medium": [0.034, 0.062],
      "high":   [0.133, 0.22]
    },
    "gpt-image-2": {
      "low":    [0.0058, 0.0228],
      "medium": [0.0492, 0.2016],
      "high":   [0.198, 0.804]
    }
  };
  $range := $lookup($lookup($ranges, widgets.model), widgets.quality);
  $nRaw := widgets.n;
  $n := ($nRaw != null and $nRaw != 0) ? $nRaw : 1;
  ($n = 1)
    ? {"type":"range_usd","min_usd": $range[0], "max_usd": $range[1], "format": {"approximate": true}}
    : {
        "type":"range_usd",
        "min_usd": $range[0] * $n,
        "max_usd": $range[1] * $n,
        "format": { "suffix": "/Run", "approximate": true }
      }
)
